 func parseECSTags(tags []ecs.Tag) ipamTypes.Tags {
 	result := make(ipamTypes.Tags, len(tags))
 	for _, tag := range tags {
 		result[tag.TagKey] = tag.TagValue
 	}
 	return result
 }

